import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contributing.md","filePath":"guide/contributing.md"}'),o={name:"guide/contributing.md"};function i(d,e,c,l,r,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Contributions are welcome under the Apache License 2.0 (documentation and examples under CC BY 4.0). <a href="https://github.com/TerminalDZ/vidcreat/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> in the repository covers the development setup on Windows, macOS and Linux, commit conventions and the quality gate every pull request must pass:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:unit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span></code></pre></div><p>This page describes the four most common contributions.</p><h2 id="add-a-component" tabindex="-1">Add a component <a class="header-anchor" href="#add-a-component" aria-label="Permalink to &quot;Add a component&quot;">​</a></h2><ol><li>Add its prop schema and defaults in <code>packages/core/src/components/</code>. Props are strict Zod objects; give every prop a sensible default so the editor can insert the component with no input.</li><li>Add its runtime in <code>packages/runtime/src/components/</code>. It draws DOM/SVG for any time <code>t</code> and must stay pure: no <code>Date.now()</code>, no unseeded randomness, no timers. Support right-to-left layout.</li><li>Add a scene that shows it to the gallery in <code>fixtures/golden/components/episode.yaml</code>.</li><li>Refresh the golden frames and review every changed image: <code>UPDATE_GOLDEN=1 pnpm test:browser</code> (PowerShell: <code>$env:UPDATE_GOLDEN=1; pnpm test:browser; Remove-Item Env:UPDATE_GOLDEN</code>).</li><li>Regenerate the documentation with <code>pnpm docs:gen</code>. The <a href="./../reference/components.html">components reference</a> picks up the schema and the new gallery frame.</li></ol><p>The <code>reelforge-contribute-component</code> skill has a detailed checklist.</p><h2 id="add-a-theme" tabindex="-1">Add a theme <a class="header-anchor" href="#add-a-theme" aria-label="Permalink to &quot;Add a theme&quot;">​</a></h2><p>Copy <code>themes/default.theme.yaml</code> to <code>themes/&lt;name&gt;.theme.yaml</code> and change the tokens, or generate one with <code>pnpm reelforge theme new &lt;name&gt; --accent &quot;#hex&quot;</code>. Use only bundled fonts and keep the contrast rules in <a href="./themes.html">Themes and branding</a>: the theme test checks WCAG AA for every bundled theme. Check it with an example episode (<code>meta.theme: &lt;name&gt;</code>) and <code>reelforge snap</code>. Themes contain no code.</p><h2 id="add-an-industry-pack" tabindex="-1">Add an industry pack <a class="header-anchor" href="#add-an-industry-pack" aria-label="Permalink to &quot;Add an industry pack&quot;">​</a></h2><p>A pack lives in <code>packs/&lt;id&gt;/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packs/&lt;id&gt;/</span></span>
<span class="line"><span>  pack.yaml                     manifest: names, description, theme, blueprints, templates and slots</span></span>
<span class="line"><span>  templates/&lt;template&gt;.en.yaml  an episode with {{slot}} placeholders (one file per language)</span></span>
<span class="line"><span>  templates/&lt;template&gt;.ar.yaml</span></span>
<span class="line"><span>  examples/&lt;name&gt;-en/           a complete example episode (generated)</span></span>
<span class="line"><span>  examples/&lt;name&gt;-ar/</span></span></code></pre></div><ol><li>Open an <a href="https://github.com/TerminalDZ/vidcreat/issues/new?template=industry_pack_request.yml" target="_blank" rel="noreferrer">industry pack request</a> first so the scope can be agreed.</li><li>Write <code>pack.yaml</code>; it is validated by the pack schema in <code>packages/core/src/packs.ts</code> when loaded. Use fictional organization names only, and keep slot limits tight enough that text fits its box.</li><li>Write each template in English and Arabic. Every element should enter on a word of the script.</li><li>Add the example to <code>scripts/gen-pack-examples.mjs</code> and run it; then validate the examples and render them with <code>--silent</code>.</li><li>Add a playbook in <code>skills/reelforge-industry-playbooks/references/&lt;id&gt;.md</code> (audience, tone, typical episodes, compliance), and run <code>pnpm docs:gen</code> to update the <a href="./../reference/packs.html">pack catalog</a>.</li></ol><h2 id="add-a-skill" tabindex="-1">Add a skill <a class="header-anchor" href="#add-a-skill" aria-label="Permalink to &quot;Add a skill&quot;">​</a></h2><p>Skills live in <code>skills/&lt;name&gt;/SKILL.md</code> in the Agent Skills format: YAML front matter with a <code>name</code> and a one-sentence <code>description</code> of when to use the skill, followed by concise Markdown instructions; longer material goes in <code>references/</code>. Keep each skill focused on one task, refer only to commands and files that exist, and test it by following the instructions yourself on a fresh episode. <code>pnpm check:skills</code> (part of <code>pnpm lint</code>) checks the format, and <code>get_guide</code> serves the new skill automatically.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The site and the offline documentation are built from the same Markdown in <code>docs/</code>:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>pnpm docs:gen</code></td><td>Regenerates the reference pages, component frames, <code>docs/components.md</code>, <code>llms-full.txt</code></td></tr><tr><td><code>pnpm docs:dev</code></td><td>Serves the site locally with live reload</td></tr><tr><td><code>pnpm docs:site</code></td><td>Builds the public site (base <code>/vidcreat/</code>) into <code>docs/.site</code> (fails on dead links)</td></tr><tr><td><code>pnpm docs:local</code></td><td>Builds the same site with base <code>/docs/</code> into <code>documentation/site</code>, which the dashboard serves at <code>/docs/</code></td></tr><tr><td><code>pnpm docs</code></td><td>Runs <code>docs:gen</code>, the single-file <code>documentation/index.html</code> (English and Arabic) and <code>docs:local</code>; commit result</td></tr></tbody></table><p>English pages live in <code>docs/guide/</code> and <code>docs/reference/</code>; their Arabic versions mirror them under <code>docs/ar/</code>. Never edit generated pages by hand: CI runs <code>node scripts/check-docs-fresh.mjs</code> and fails when they are out of date. In Arabic pages, keep technical terms, commands and YAML keys in English inside backticks, and avoid starting a paragraph with a Latin word.</p><h2 id="decision-records" tabindex="-1">Decision records <a class="header-anchor" href="#decision-records" aria-label="Permalink to &quot;Decision records&quot;">​</a></h2><p>For a significant design change, add an ADR in <code>docs/adr/</code> (next number, context, decision, consequences).</p>`,21)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
